<?php $storeIndex = $storesById ?? array_column(app('storeRepository')->all(), null, 'id'); ?>
<div class="stack"><div class="hero-actions"><div><h1>Gestione coupon</h1><p class="muted">CRUD coupon, stato, priorità e deduplicazione TradeDoubler.</p></div><a class="btn" href="<?php echo e(url('/admin/offers/create')); ?>">Nuovo coupon</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Titolo</th><th>Tipo</th><th>Store</th><th>Stato</th><th>Azioni</th></tr></thead><tbody><?php foreach ($items as $offer): ?><?php $store = $storeIndex[(int) $offer['store_id']] ?? null; ?><tr><td><?php echo e($offer['title']); ?><br><small><?php echo e($offer['discount']); ?> · <?php echo e($offer['expires_at']); ?></small></td><td><?php echo e($offer['type']); ?></td><td><?php echo e($store['name'] ?? 'Store'); ?></td><td><span class="tag <?php echo strtolower($offer['status']) === 'expired' ? 'status-expired' : (strtolower($offer['status']) === 'scheduled' ? 'status-scheduled' : 'status-active'); ?>"><?php echo e($offer['status']); ?></span></td><td><div class="table-actions"><a class="btn btn-secondary" href="<?php echo e(url('/admin/offers/' . $offer['id'] . '/edit')); ?>">Modifica</a><form action="<?php echo e(url('/admin/offers/' . $offer['id'] . '/status')); ?>" method="post"><?php echo csrf_field(); ?><input type="hidden" name="status" value="<?php echo e($offer['status'] === 'ACTIVE' ? 'EXPIRED' : 'ACTIVE'); ?>"><button class="btn btn-secondary" type="submit">Cambia stato</button></form><form action="<?php echo e(url('/admin/offers/' . $offer['id'] . '/delete')); ?>" method="post"><?php echo csrf_field(); ?><button class="btn btn-danger" type="submit">Elimina</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div>
